<?php
session_start();
if (empty($_SESSION['qms_logged_in'])) { header('Location: login.php'); exit; }
require_once __DIR__ . '/config/database.php'; require_once __DIR__ . '/includes/risk-functions.php';
$userId=(int)($_SESSION['qms_user_id']??0); $super=($_SESSION['qms_role']??'')==='super_admin'; $companyIds=qmsRiskScope($pdo,$userId,$super);
$companies=[]; if($companyIds){$marks=implode(',',array_fill(0,count($companyIds),'?'));$stmt=$pdo->prepare("SELECT id,company_name FROM companies WHERE id IN ($marks) ORDER BY company_name");$stmt->execute($companyIds);$companies=$stmt->fetchAll(PDO::FETCH_ASSOC);}
$data=['company_id'=>0,'title'=>'','category'=>'','responsible_person'=>'','due_date'=>'','status'=>'open','description'=>'','existing_controls'=>'','treatment_plan'=>'','initial_likelihood'=>'','initial_impact'=>'','residual_likelihood'=>'','residual_impact'=>'','note'=>'']; $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{qmsRiskVerifyCsrf($_POST['csrf']??null);$data=qmsRiskValidate($_POST,$companyIds,true);$pdo->beginTransaction();$stmt=$pdo->prepare('INSERT INTO risks (company_id,title,category,responsible_person,due_date,status,description,existing_controls,treatment_plan,initial_likelihood,initial_impact,residual_likelihood,residual_impact,created_by,updated_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$stmt->execute([$data['company_id'],$data['title'],$data['category']?:null,$data['responsible_person']?:null,$data['due_date']?:null,$data['status'],$data['description'],$data['existing_controls']?:null,$data['treatment_plan']?:null,$data['initial_likelihood'],$data['initial_impact'],$data['residual_likelihood'],$data['residual_impact'],$userId,$userId]);$id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO risk_history (risk_id,status,residual_likelihood,residual_impact,note,changed_by) VALUES (?,?,?,?,?,?)')->execute([$id,$data['status'],$data['residual_likelihood'],$data['residual_impact'],$data['note']?:'Risk kaydı oluşturuldu.',$userId]);$pdo->commit();header('Location: risk-detail.php?id='.$id.'&risk=created');exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof PDOException?'Risk kaydedilemedi.':$e->getMessage();}}
function rcEsc($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}$activeNav='risks';
?>
<!doctype html><html lang="tr"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>QuAmi Yeni Risk</title><link rel="stylesheet" href="assets/css/style.css"><link rel="stylesheet" href="assets/css/risks.css"></head><body class="has-sidebar"><?php require __DIR__.'/includes/app-sidebar.php'; ?><header class="topbar"><div class="topbar-inner"><div class="page-title-block"><strong data-i18n="newRiskTitle">Yeni Risk</strong><span data-i18n="newRiskText">Riski ve ilk değerlendirmeyi kaydedin.</span></div><div class="topbar-actions"><button class="topbar-button" id="languageToggle">EN</button><button class="topbar-button" id="themeToggle" aria-label="Tema değiştir">🌙</button></div></div></header><main class="page-container narrow-page"><section class="page-heading page-heading-actions"><div><span class="section-kicker" data-i18n="riskRegisterKicker">Risk Kayıtları</span><h1 data-i18n="newRiskTitle">Yeni Risk</h1><p data-i18n="riskScaleNotice">Puan = Olasılık × Etki. Eşikler proje varsayımıdır.</p></div><a class="secondary-button" href="risks.php" data-i18n="backToRisksButton">Risklere Dön</a></section><?php if($error):?><div class="form-message error"><?=rcEsc($error)?></div><?php endif;?><section class="form-panel"><form method="post" class="auditor-form"><input type="hidden" name="csrf" value="<?=rcEsc(qmsRiskCsrf())?>"><div class="form-grid"><label class="form-field form-field-wide"><span data-i18n="companySelectLabel">Şirket</span><select name="company_id" required><option value="">Şirket seçin</option><?php foreach($companies as $c):?><option value="<?=$c['id']?>" <?=$data['company_id']==$c['id']?'selected':''?>><?=rcEsc($c['company_name'])?></option><?php endforeach;?></select></label><label class="form-field form-field-wide"><span data-i18n="riskTitleLabel">Risk Tanımı</span><input name="title" maxlength="255" value="<?=rcEsc($data['title'])?>" required></label><label class="form-field"><span data-i18n="riskCategoryLabel">Kategori</span><input name="category" maxlength="100" value="<?=rcEsc($data['category'])?>"></label><label class="form-field"><span data-i18n="responsiblePersonLabel">Sorumlu</span><input name="responsible_person" maxlength="150" value="<?=rcEsc($data['responsible_person'])?>"></label><label class="form-field"><span data-i18n="dueDateLabel">Termin</span><input type="date" name="due_date" value="<?=rcEsc($data['due_date'])?>"></label><label class="form-field"><span data-i18n="riskStatusLabel">Durum</span><select name="status"><option value="open">Açık</option><option value="monitoring">İzlemede</option><option value="treated">Önlem Uygulandı</option><option value="closed">Kapalı</option></select></label><label class="form-field form-field-wide"><span data-i18n="riskDescriptionLabel">Risk Açıklaması</span><textarea name="description" rows="4" required><?=rcEsc($data['description'])?></textarea></label><label class="form-field form-field-wide"><span data-i18n="existingControlsLabel">Mevcut Kontroller</span><textarea name="existing_controls" rows="4"><?=rcEsc($data['existing_controls'])?></textarea></label><label class="form-field form-field-wide"><span data-i18n="treatmentPlanLabel">Önlem Planı</span><textarea name="treatment_plan" rows="4"><?=rcEsc($data['treatment_plan'])?></textarea></label><?=qmsRiskScoreFields($data)?><label class="form-field form-field-wide"><span data-i18n="trackingNoteLabel">Takip Notu</span><textarea name="note" rows="3"><?=rcEsc($data['note'])?></textarea></label></div><div class="form-actions"><button class="primary-button" data-i18n="saveRiskButton">Riski Kaydet</button></div></form></section></main><script src="assets/js/theme.js"></script><script src="assets/js/language.js"></script><script src="assets/js/sidebar.js"></script></body></html>
<?php function qmsRiskScoreFields(array $d):string{ob_start();foreach(['initial_likelihood'=>'Başlangıç Olasılık','initial_impact'=>'Başlangıç Etki','residual_likelihood'=>'Önlem Sonrası Olasılık','residual_impact'=>'Önlem Sonrası Etki'] as $name=>$label):?><label class="form-field"><span><?=$label?> (1–5)</span><select name="<?=$name?>" <?=str_starts_with($name,'initial_')?'required':''?>><option value="">Seçin</option><?php for($i=1;$i<=5;$i++):?><option value="<?=$i?>" <?=(string)$d[$name]===(string)$i?'selected':''?>><?=$i?></option><?php endfor;?></select></label><?php endforeach;return ob_get_clean();}?>
